};

const deterministicFallbackReply = fallbackByCode[responseCode] || null;

// ── Return facts (no reply — DeepSeek #2 generates it) ──
const currentAgentReply = (() => {
  try {
    const normalized = (() => { try { const r = $('Validate Repaired Contract (Deterministic)').first().json; if (r && r._contract_status === 'VALID') return r; } catch (_) {} return $('Normalize Agent Output (Deterministic)').first().json || {}; })();
    const reply = String(normalized.agent_reply || normalized.contract?.reply || '').trim();
    return errorFollowupNeedsFallback && recoveryGenericReply ? null : (reply || null);
  } catch (_) { return null; }
})();
return [{ json: {
  ...$json,
  system_decision: { ...decision, response_code: responseCode, escalation_requested: escalationRequested },
  escalation_requested: escalationRequested,
  agent_reply: errorFollowupNeedsFallback ? null : (currentAgentReply || String($json.agent_reply || '').trim() || null),
  facts: safeFacts,
  response_code: responseCode,
  operation_status: operationStatus,
  success,
  retryable,
  appointment_id: appointmentId || null,
  booking_number: bookingNumber,
  queue_number: queueNumber,
  queue_path: queuePath,
  queue_url: queueUrl,
  queue_expires_at: queueExpiresAt,
  patient_name: String(execution.patient_name || '').trim() || null,
  patient_phone: String(execution.patient_phone || '').trim() || null,
  missing_human_fields: missingHuman,
  next_best_missing_human_field: nextBestMissing,
  deterministic_fallback_reply: deterministicFallbackReply,
  confirmation_target: confirmationTarget,
  contract
} }];

const ctx = $('Normalize & Validate').item.json;
const previous = $json.state_data && typeof $json.state_data === 'object' ? $json.state_data : {};
const requestedOperationId = String(ctx.operation_id || '').trim();
const publicBookingNumber = String(previous.booking_number || '').trim();
const isCompletedCreateReplay = requestedOperationId !== ''
  && previous.operation_action === 'create_appointment'
  && ['success', 'completed'].includes(String(previous.operation_status || ''))
  && String(previous.operation_id || '') === requestedOperationId
  && String(previous.appointment_id || '').trim() !== '';
const replayReply = publicBookingNumber
  ? `تم تأكيد الحجز بالفعل ورقم الحجز ${publicBookingNumber}`
  : 'تم تأكيد الحجز بالفعل';

const replayDecision = isCompletedCreateReplay ? {
  intent: 'booking',
  proposed_action: 'none',
  action: 'create_appointment',
  allowed: false,
  response_code: 'IDEMPOTENT_REPLAY',
  operation_id: previous.operation_id,
  appointment_id: previous.appointment_id,
  replayed: true,
  confirmation_state: 'confirmed',
  confirmation_target: null,
  final_reply: replayReply
} : null;

const replayProposal = isCompletedCreateReplay ? {
  intent: 'booking',
  proposed_action: 'none',
  confidence: 1,
  proposed_reply: replayDecision.final_reply,
  slot_state: previous.slot_state || {},
  booking_context: previous.booking_context || {},
  confirmation_required: false,
  user_confirmation_signal: false,
  confirmation_target: null,
  appointment_id: previous.appointment_id,
  cancellation_reason: 'user_requested',
  cancelled_by: null,
  escalate: false
} : null;

return [{ json: { ...$json, replay_gate: { matched: isCompletedCreateReplay }, ...(replayDecision ? { system_decision: replayDecision, proposal: replayProposal } : {}) } }];

